/**
 * Shared Igloohome duration (hourly) AlgoPIN helper with collision-safe variance
 * allocation.
 *
 * Hourly AlgoPIN is the bridge-down fallback. The algorithm is deterministic:
 * the same deviceId + startDate + endDate + variance always yields the same
 * code. Igloo allows 3 variances (1-3) per exact duration (start AND end).
 *
 * startDate is floored to the UTC hour; endDate is ceiled to the next UTC hour
 * so we never cut a rental short. Duration must be 1–672 hours.
 *
 * Collision guarantee: a partial unique index on
 * `rental_access_codes (lock_id, start_time, end_time, variance)
 *  WHERE status = 'active'` is the source of truth. The pre-insert query is an
 * optimization only. A concurrent race is handled by catching unique-violation
 * (23505) and retrying the next free variance.
 */

import {
  ALGOPIN_HOURLY_MAX_HOURS,
  ALGOPIN_HOURLY_MIN_HOURS,
  formatAlgoPinEndIso,
  formatAlgoPinStartIso,
} from "./pinTiming.ts";

export const IGLOOHOME_ALGOPIN_API_BASE_URL = "https://api.igloodeveloper.co/igloohome";

const MIN_VARIANCE = 1;
const MAX_VARIANCE = 3;

// deno-lint-ignore no-explicit-any
type SupabaseClient = any;

async function readResponse(res: Response) {
  const text = await res.text();
  try {
    return { text, json: text ? JSON.parse(text) : null };
  } catch {
    return { text, json: null };
  }
}

type IglooAlgoPinResponse =
  | { success: true; pin: string; pinId: string }
  | { success: false; error: string; rawResponse?: unknown };

async function requestHourlyAlgoPinFromIgloo(
  accessToken: string,
  lockId: string,
  startDate: string,
  endDate: string,
  variance: number,
  accessName: string,
): Promise<IglooAlgoPinResponse> {
  const res = await fetch(`${IGLOOHOME_ALGOPIN_API_BASE_URL}/devices/${lockId}/algopin/hourly`, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${accessToken}`,
      "Content-Type": "application/json",
      Accept: "application/json",
    },
    body: JSON.stringify({ accessName, startDate, endDate, variance }),
  });
  const body = await readResponse(res);
  if (!res.ok && res.status !== 201) {
    return {
      success: false,
      error: `Hourly AlgoPIN failed with status ${res.status}`,
      rawResponse: body.json ?? body.text,
    };
  }
  const pin = String(body.json?.pin || body.json?.access_code || body.json?.code || body.json?.data?.pin || "");
  if (!pin) {
    return { success: false, error: "Hourly AlgoPIN succeeded but no PIN value in response", rawResponse: body.json };
  }
  return { success: true, pin, pinId: String(body.json?.pinId || body.json?.id || "") };
}

/**
 * Variances already claimed by other *active* hourly AlgoPINs on this lock for
 * this exact (hour-aligned) start+end duration. Optimization only.
 */
async function usedVariances(
  supabase: SupabaseClient,
  lockId: string,
  startDate: string,
  endDate: string,
): Promise<Set<number>> {
  const { data, error } = await supabase
    .from("rental_access_codes")
    .select("variance")
    .eq("lock_id", lockId)
    .eq("start_time", startDate)
    .eq("end_time", endDate)
    .eq("status", "active")
    .not("variance", "is", null);
  if (error) {
    console.warn("[algoPin] Failed to query used variances, trying full 1-3 range:", error.message);
    return new Set();
  }
  return new Set(
    (data ?? [])
      .map((row: { variance: number | null }) => Number(row.variance))
      .filter((v: number) => Number.isFinite(v)),
  );
}

function isUniqueViolation(error: { code?: string; message?: string } | null | undefined): boolean {
  if (!error) return false;
  if (error.code === "23505") return true;
  return /duplicate key value violates unique constraint/i.test(error.message || "");
}

export type CreateAlgoPinWithVarianceOptions = {
  supabase: SupabaseClient;
  accessToken: string;
  lockId: string;
  /** Raw ISO start; floored to the top of the UTC hour before use. */
  startDate: string;
  /** Raw ISO end; ceiled to the next UTC hour before use. */
  endDate: string;
  accessName: string;
  /**
   * Remaining `rental_access_codes` columns for the insert (order_id,
   * customer_email, status, etc). Do not include `access_pin`, `pin_id`,
   * `pin_type`, `lock_id`, `variance`, `start_time`, or `end_time` — this
   * helper fills those in.
   */
  insertRow: Record<string, unknown>;
};

export type CreateAlgoPinWithVarianceResult =
  | {
    success: true;
    exhausted: false;
    pin: string;
    pinId: string;
    variance: number;
    startDate: string;
    endDate: string;
    kind: "hourly";
    /** rental_access_codes.id (uuid) of the inserted row. */
    rowId: string | null;
    error?: undefined;
  }
  | {
    success: false;
    /**
     * True when every variance slot (1-3) for this lock + duration is
     * already claimed. Callers should fall back to the bridge path rather
     * than treat this as a hard failure.
     */
    exhausted: boolean;
    error: string;
  };

/**
 * Create a duration (hourly) AlgoPIN using an unused variance (1-3) for this
 * lock + exact start/end, and persist it to `rental_access_codes` in the same
 * call (the insert is what lets us detect and retry past a collision race).
 *
 * Returns `exhausted: true` (not a hard failure) when all 3 variances are
 * already active for this lock + duration.
 */
export async function createAlgoPinWithVariance(
  opts: CreateAlgoPinWithVarianceOptions,
): Promise<CreateAlgoPinWithVarianceResult> {
  const { supabase, accessToken, lockId, accessName, insertRow } = opts;
  const startDate = formatAlgoPinStartIso(opts.startDate);
  const endDate = formatAlgoPinEndIso(opts.endDate);

  const startMs = new Date(startDate).getTime();
  const endMs = new Date(endDate).getTime();
  if (!Number.isFinite(startMs) || !Number.isFinite(endMs) || endMs <= startMs) {
    return {
      success: false,
      exhausted: false,
      error: `Hourly AlgoPIN window is invalid (start=${startDate}, end=${endDate})`,
    };
  }
  const hours = (endMs - startMs) / (60 * 60 * 1000);
  if (hours < ALGOPIN_HOURLY_MIN_HOURS || hours > ALGOPIN_HOURLY_MAX_HOURS) {
    return {
      success: false,
      exhausted: false,
      error:
        `Hourly AlgoPIN duration ${hours}h is outside ${ALGOPIN_HOURLY_MIN_HOURS}–${ALGOPIN_HOURLY_MAX_HOURS} hours`,
    };
  }

  const used = await usedVariances(supabase, lockId, startDate, endDate);
  const candidates: number[] = [];
  for (let v = MIN_VARIANCE; v <= MAX_VARIANCE; v++) {
    if (!used.has(v)) candidates.push(v);
  }

  if (candidates.length === 0) {
    return {
      success: false,
      exhausted: true,
      error:
        `All ${MAX_VARIANCE} hourly AlgoPIN variance slots are already active for lock ${lockId} ${startDate}→${endDate}`,
    };
  }

  const { end_time: _ignoredEnd, start_time: _ignoredStart, ...insertRest } = insertRow;

  let lastError = "";
  for (const variance of candidates) {
    const algo = await requestHourlyAlgoPinFromIgloo(
      accessToken,
      lockId,
      startDate,
      endDate,
      variance,
      accessName,
    );
    if (!algo.success) {
      return { success: false, exhausted: false, error: algo.error };
    }

    const { data: inserted, error: insertError } = await supabase
      .from("rental_access_codes")
      .insert({
        ...insertRest,
        access_pin: algo.pin,
        pin_id: algo.pinId || "",
        pin_type: "algopin",
        lock_id: lockId,
        variance,
        start_time: startDate,
        end_time: endDate,
      })
      .select("id")
      .single();

    if (!insertError) {
      return {
        success: true,
        exhausted: false,
        pin: algo.pin,
        pinId: algo.pinId,
        variance,
        startDate,
        endDate,
        kind: "hourly",
        rowId: inserted?.id ?? null,
      };
    }

    if (isUniqueViolation(insertError)) {
      console.warn(
        `[algoPin] Variance ${variance} lost the race for lock ${lockId} ${startDate}→${endDate} — retrying next slot`,
      );
      lastError = insertError.message;
      continue;
    }

    return { success: false, exhausted: false, error: insertError.message };
  }

  return {
    success: false,
    exhausted: true,
    error: lastError ||
      `All available hourly AlgoPIN variance slots collided for lock ${lockId} ${startDate}→${endDate}`,
  };
}

const ALLOWED_HEADERS = 'authorization, x-client-info, apikey, content-type';
const ALLOWED_METHODS = 'GET, POST, PUT, PATCH, DELETE, OPTIONS';

function parseAllowedOrigins(): Set<string> {
  const raw = Deno.env.get('ALLOWED_ORIGINS') ?? '';
  return new Set(
    raw
      .split(',')
      .map((origin) => origin.trim())
      .filter(Boolean),
  );
}

let cachedOrigins: Set<string> | null = null;

function getAllowedOrigins(): Set<string> {
  if (!cachedOrigins) {
    cachedOrigins = parseAllowedOrigins();
  }
  return cachedOrigins;
}

/** Origin-aware CORS headers. Set ALLOWED_ORIGINS (comma-separated) in env. */
export function getCorsHeaders(req: Request): Record<string, string> {
  const headers: Record<string, string> = {
    'Access-Control-Allow-Headers': ALLOWED_HEADERS,
    'Access-Control-Allow-Methods': ALLOWED_METHODS,
  };

  const origin = req.headers.get('Origin');
  if (origin && getAllowedOrigins().has(origin)) {
    headers['Access-Control-Allow-Origin'] = origin;
    headers['Vary'] = 'Origin';
  }

  return headers;
}

/**
 * Delivery vs yard self-pickup. PIN create / PIN email / lock confirm must skip delivery.
 *
 * Primary flag: addons.isDelivery (and deliveryService). Also honor delivery_type and
 * always-delivered catalog services (dumpster #1, dump trailer with delivery #4) when
 * the JSON flag is missing.
 */

function asRecord(value: unknown): Record<string, unknown> {
  if (value && typeof value === "object" && !Array.isArray(value)) {
    return value as Record<string, unknown>;
  }
  if (typeof value === "string") {
    try {
      const parsed = JSON.parse(value);
      if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) {
        return parsed as Record<string, unknown>;
      }
    } catch {
      // ignore
    }
  }
  return {};
}

/** Catalog services that are always company delivery (not a yard padlock pickup). */
export const ALWAYS_DELIVERY_PLAN_IDS = [1, 4];

export function isDeliveryBooking(
  booking: Record<string, unknown> | null | undefined,
): boolean {
  if (!booking) return false;
  const addons = asRecord(booking.addons);
  const plan = asRecord(booking.plan);
  if (addons.isDelivery === true || addons.deliveryService === true) return true;
  if (booking.delivery_service === true) return true;
  if (String(booking.delivery_type || "").toLowerCase() === "delivery") return true;
  const planId = Number(plan.id);
  return ALWAYS_DELIVERY_PLAN_IDS.includes(planId);
}

/**
 * True when this booking should get a yard padlock PIN (create, confirm, email/SMS).
 * Delivery is always excluded, even if the plan name contains "trailer".
 */
export function bookingNeedsYardLockPin(
  booking: Record<string, unknown> | null | undefined,
): boolean {
  if (!booking || isDeliveryBooking(booking)) return false;
  const plan = asRecord(booking.plan);
  const name = String(plan.name ?? booking.service_name ?? "").toLowerCase();
  const serviceType = String(plan.service_type ?? booking.service_type ?? "");
  return (
    serviceType === "trailer_rental" ||
    Number(plan.id) === 2 ||
    Number(plan.id) === 5 ||
    name.includes("dump loader") ||
    name.includes("dump trailer") ||
    name.includes("trailer") ||
    plan.customer_pickup === true
  );
}

/**
 * Flexible parsers for Igloohome activity payloads.
 *
 * Bridge jobType 15 (GET_LOGS) often completes with only `opResult: { result: 0 }`
 * (operation success) and no log array. Real history is on:
 *   GET /igloohome/devices/{deviceId}/activity
 * after the Bridge pull uploads logs to the cloud.
 */

export const IGLOOHOME_API_BASE_URL = "https://api.igloodeveloper.co/igloohome";

export type LockEventKind = "unlock" | "lock" | "breakin";

export type LockActivityEvent = {
  eventType: LockEventKind;
  eventTimestamp: string;
  pinCode: string | null;
  logType: number | null;
  keyId: string | null;
  operationId: string | null;
  deviceId: string | null;
  raw: Record<string, unknown>;
};

/**
 * Numeric activity log codes from the igloohome webhook (event type 5).
 * These arrive as `logType` on each entry in `activityLogs[]`.
 */
export const LOCK_LOG_TYPES = new Set([
  37, // Bluetooth lock
  49, // lock via keypad/button
  51, // lock with key/thumbturn
]);

export const UNLOCK_LOG_TYPES = new Set([
  11, // Bluetooth unlock
  18,
  19,
  20, // one-time PIN
  21,
  22,
  23,
  24,
  25,
  26, // unlock with the various PIN types
  50, // unlock via button
  52, // unlock with key/thumbturn
  56, // fingerprint unlock
]);

export const BREAKIN_LOG_TYPE = 53;

/** Map a numeric igloohome logType to an event kind, or null if not access-related. */
export function logTypeToEventKind(logType: unknown): LockEventKind | null {
  const n = typeof logType === "number"
    ? logType
    : typeof logType === "string" && /^\d+$/.test(logType.trim())
    ? Number(logType.trim())
    : null;
  if (n === null) return null;
  if (n === BREAKIN_LOG_TYPE) return "breakin";
  if (UNLOCK_LOG_TYPES.has(n)) return "unlock";
  if (LOCK_LOG_TYPES.has(n)) return "lock";
  return null;
}

function extractLogType(entry: Record<string, unknown>): number | null {
  const val = entry.logType ?? entry.log_type;
  if (typeof val === "number" && Number.isFinite(val)) return val;
  if (typeof val === "string" && /^\d+$/.test(val.trim())) return Number(val.trim());
  return null;
}

function asRecord(value: unknown): Record<string, unknown> | null {
  if (value && typeof value === "object" && !Array.isArray(value)) {
    return value as Record<string, unknown>;
  }
  return null;
}

function pickString(obj: Record<string, unknown>, keys: string[]): string | null {
  for (const key of keys) {
    const val = obj[key];
    if (typeof val === "string" && val.trim()) return val.trim();
    if (typeof val === "number") return String(val);
  }
  return null;
}

function isFailedActivity(raw: string | null, entry: Record<string, unknown>): boolean {
  const lower = (raw || "").toLowerCase();
  if (lower.includes("fail") || lower.includes("denied") || lower.includes("invalid")) {
    return true;
  }
  const desc = String(entry.description || "").toLowerCase();
  if (desc.includes("fail") || desc.includes("denied")) return true;
  return false;
}

function normalizeEventType(raw: string | null): LockEventKind | null {
  if (!raw) return null;
  const lower = raw.toLowerCase().replace(/[\s_-]+/g, "");
  // Ignore non-access noise (time sync, battery, etc.)
  if (
    lower.includes("settime") ||
    lower.includes("battery") ||
    lower.includes("bluetooth") ||
    lower.includes("firmware") ||
    lower.includes("heartbeat")
  ) {
    return null;
  }
  if (
    lower.includes("unlock") ||
    lower === "open" ||
    lower === "unlocked" ||
    lower === "pinunlock" ||
    lower === "accessgranted"
  ) {
    return "unlock";
  }
  if (
    lower.includes("relock") ||
    lower.includes("autolock") ||
    lower === "lock" ||
    lower === "close" ||
    lower === "locked" ||
    lower.includes("manualock") ||
    lower.includes("manuallock") ||
    (lower.includes("lock") && !lower.includes("unlock") && !lower.includes("block"))
  ) {
    return "lock";
  }
  return null;
}

/**
 * Webhook activity entries carry `entryDate` as epoch seconds. That is the
 * authoritative time the event happened at the lock — logs can be batched and
 * delivered long after the fact, so never fall back to delivery time.
 */
function extractEpochTimestamp(entry: Record<string, unknown>): string | null {
  for (const key of ["entryDate", "entry_date", "eventDate", "logDate"]) {
    const val = entry[key];
    let num: number | null = null;
    if (typeof val === "number" && Number.isFinite(val)) num = val;
    else if (typeof val === "string" && /^\d{9,13}$/.test(val.trim())) num = Number(val.trim());
    if (num === null || num <= 0) continue;
    // Values below ~1e11 are seconds; above that they are already milliseconds.
    const ms = num < 1e11 ? num * 1000 : num;
    const date = new Date(ms);
    if (!Number.isNaN(date.getTime())) return date.toISOString();
  }
  return null;
}

function extractTimestamp(entry: Record<string, unknown>): string | null {
  const epoch = extractEpochTimestamp(entry);
  if (epoch) return epoch;
  const raw = pickString(entry, [
    "localActionAt",
    "activityTimeAt",
    "timestamp",
    "eventTimestamp",
    "event_timestamp",
    "time",
    "date",
    "createdAt",
    "created_at",
    "lockTime",
    "activityTime",
  ]);
  if (!raw) return null;
  const ms = new Date(raw).getTime();
  if (Number.isNaN(ms)) return null;
  return new Date(ms).toISOString();
}

function extractPin(entry: Record<string, unknown>): string | null {
  const direct = pickString(entry, [
    "pin",
    "pinCode",
    "pin_code",
    "accessCode",
    "access_code",
    "code",
    "pinValue",
  ]);
  if (direct) return direct;
  const extra = asRecord(entry.extra);
  if (extra) {
    return pickString(extra, ["pin", "pinCode", "pin_code", "accessCode", "code"]);
  }
  return null;
}

function extractTypeRaw(entry: Record<string, unknown>): string | null {
  const typeVal = entry.activityType ?? entry.activity_type ?? entry.type ??
    entry.eventType ?? entry.event_type ?? entry.action ?? entry.operation ?? entry.op ??
    entry.logType;
  if (typeof typeVal === "number") {
    return String(typeVal);
  }
  if (typeof typeVal === "string") return typeVal;
  return null;
}

/** Parse a failed PIN attempt for diagnostics (not applied to rental state). */
export function parseFailedPinAttempt(entry: unknown): {
  eventTimestamp: string;
  pinCode: string | null;
  activityType: string;
} | null {
  const obj = asRecord(entry);
  if (!obj) return null;
  const typeRaw = extractTypeRaw(obj);
  if (!isFailedActivity(typeRaw, obj)) return null;
  const lower = (typeRaw || "").toLowerCase();
  if (!lower.includes("unlock") && !lower.includes("pin")) return null;
  const eventTimestamp = extractTimestamp(obj);
  if (!eventTimestamp) return null;
  return {
    eventTimestamp,
    pinCode: extractPin(obj),
    activityType: typeRaw || "PIN_UNLOCK_FAILED",
  };
}

/** Parse a single activity log entry into a normalized event, or null if unusable. */
export function parseActivityLogEntry(entry: unknown): LockActivityEvent | null {
  const obj = asRecord(entry);
  if (!obj) return null;

  // Nested data wrappers
  const nested = asRecord(obj.data) || asRecord(obj.event) || asRecord(obj.activity) || obj;
  const logType = extractLogType(nested) ?? extractLogType(obj);
  const eventTimestamp = extractTimestamp(nested) || extractTimestamp(obj);
  if (!eventTimestamp) return null;

  // Numeric logType is authoritative when present — the webhook sends codes,
  // not descriptive strings, so this must win over the text heuristics below.
  let eventType = logTypeToEventKind(logType);
  if (!eventType) {
    if (logType !== null) return null;
    const typeRaw = extractTypeRaw(nested) || extractTypeRaw(obj);
    if (isFailedActivity(typeRaw, nested) || isFailedActivity(typeRaw, obj)) return null;
    eventType = normalizeEventType(typeRaw);
  }
  if (!eventType) return null;

  return {
    eventType,
    eventTimestamp,
    pinCode: extractPin(nested) || extractPin(obj),
    logType,
    keyId: pickString(nested, ["keyId", "key_id"]) || pickString(obj, ["keyId", "key_id"]),
    operationId: pickString(nested, ["operationId", "operation_id"]) ||
      pickString(obj, ["operationId", "operation_id"]),
    deviceId: pickString(nested, ["deviceId", "device_id", "lockId", "productId"]) ||
      pickString(obj, ["deviceId", "device_id", "lockId", "productId"]),
    raw: obj,
  };
}

/** Strip PIN material so raw payloads can be persisted or logged safely. */
export function redactPins(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(redactPins);
  const obj = asRecord(value);
  if (!obj) return value;
  const out: Record<string, unknown> = {};
  for (const [key, val] of Object.entries(obj)) {
    if (/^(pin|newpin|oldpin|pincode|pin_code|accesscode|access_code|code)$/i.test(key)) {
      out[key] = val ? "[redacted]" : val;
      continue;
    }
    out[key] = redactPins(val);
  }
  return out;
}

/**
 * Walk a job response / webhook body and collect activity log arrays from
 * common nesting locations.
 */
export function extractActivityLogArrays(payload: unknown): unknown[][] {
  const arrays: unknown[][] = [];
  const root = asRecord(payload);
  if (!root) return arrays;

  const candidates = [
    root.activityLogs,
    root.activity_logs,
    root.logs,
    root.events,
    root.history,
    root.payload,
    asRecord(root.jobResponse)?.activityLogs,
    asRecord(root.jobResponse)?.activity_logs,
    asRecord(root.jobResponse)?.logs,
    asRecord(root.jobResponse)?.events,
    asRecord(asRecord(root.jobResponse)?.opResult || {})?.activityLogs,
    asRecord(asRecord(root.jobResponse)?.opResult || {})?.logs,
    asRecord(root.event)?.data,
    asRecord(asRecord(root.event)?.data || {})?.activityLogs,
    asRecord(asRecord(root.event)?.data || {})?.logs,
  ];

  for (const c of candidates) {
    if (Array.isArray(c)) arrays.push(c);
    else if (asRecord(c) && Array.isArray((c as Record<string, unknown>).logs)) {
      arrays.push((c as Record<string, unknown>).logs as unknown[]);
    }
  }

  // Deep scan one level for any array of objects that look like log entries
  if (arrays.length === 0) {
    for (const value of Object.values(root)) {
      if (Array.isArray(value) && value.length > 0 && asRecord(value[0])) {
        arrays.push(value);
      }
      const nested = asRecord(value);
      if (nested) {
        for (const inner of Object.values(nested)) {
          if (Array.isArray(inner) && inner.length > 0 && asRecord(inner[0])) {
            arrays.push(inner);
          }
        }
      }
    }
  }

  return arrays;
}

export function parseActivityLogsFromPayload(payload: unknown): LockActivityEvent[] {
  const events: LockActivityEvent[] = [];
  const seen = new Set<string>();
  for (const arr of extractActivityLogArrays(payload)) {
    for (const entry of arr) {
      const parsed = parseActivityLogEntry(entry);
      if (!parsed) continue;
      const key = `${parsed.eventType}|${parsed.eventTimestamp}|${parsed.pinCode || ""}`;
      if (seen.has(key)) continue;
      seen.add(key);
      events.push(parsed);
    }
  }
  // Also try treating the payload itself as a single event (webhook)
  const single = parseActivityLogEntry(payload) ||
    parseActivityLogEntry(asRecord(payload)?.event) ||
    parseActivityLogEntry(asRecord(asRecord(payload)?.event || {})?.data);
  if (single) {
    const key = `${single.eventType}|${single.eventTimestamp}|${single.pinCode || ""}`;
    if (!seen.has(key)) events.push(single);
  }
  return events.sort(
    (a, b) => new Date(a.eventTimestamp).getTime() - new Date(b.eventTimestamp).getTime(),
  );
}

/** Merge and dedupe events from multiple sources (job payload + REST activity rows). */
export function eventsFromSource(source: unknown): LockActivityEvent[] {
  if (Array.isArray(source)) {
    if (source.length === 0) return [];
    const first = asRecord(source[0]);
    // Already-normalized LockActivityEvent[]
    if (
      first &&
      (first.eventType === "unlock" || first.eventType === "lock" ||
        first.eventType === "breakin") &&
      typeof first.eventTimestamp === "string"
    ) {
      return source as LockActivityEvent[];
    }
    // Raw GET /devices/.../activity payload rows
    const events: LockActivityEvent[] = [];
    const seen = new Set<string>();
    for (const entry of source) {
      const parsed = parseActivityLogEntry(entry);
      if (!parsed) continue;
      const key = `${parsed.eventType}|${parsed.eventTimestamp}|${parsed.pinCode || ""}`;
      if (seen.has(key)) continue;
      seen.add(key);
      events.push(parsed);
    }
    return events;
  }
  return parseActivityLogsFromPayload(source);
}

export function mergeActivityEvents(
  ...sources: Array<LockActivityEvent[] | unknown>
): LockActivityEvent[] {
  const events: LockActivityEvent[] = [];
  const seen = new Set<string>();
  for (const source of sources) {
    for (const parsed of eventsFromSource(source)) {
      const key = `${parsed.eventType}|${parsed.eventTimestamp}|${parsed.pinCode || ""}`;
      if (seen.has(key)) continue;
      seen.add(key);
      events.push(parsed);
    }
  }
  return events.sort(
    (a, b) => new Date(a.eventTimestamp).getTime() - new Date(b.eventTimestamp).getTime(),
  );
}

/**
 * True when Igloohome completed GET_LOGS but returned no log array —
 * commonly `jobResponse.opResult = { result: 0 }` (success with empty body).
 * Prefer reading GET /devices/{id}/activity after the job completes.
 */
export function isEmptyActivityLogPayload(payload: unknown): boolean {
  if (parseActivityLogsFromPayload(payload).length > 0) return false;
  const root = asRecord(payload);
  const jobResponse = asRecord(root?.jobResponse);
  const opResult = asRecord(jobResponse?.opResult);
  if (!opResult) return true;
  const result = opResult.result;
  if (result === 0 || result === "0" || result === null || result === undefined) {
    return true;
  }
  if (Array.isArray(result) && result.length === 0) return true;
  if (asRecord(result)) {
    const nested = asRecord(result);
    for (const key of ["activityLogs", "activity_logs", "logs", "events", "history"]) {
      const arr = nested?.[key];
      if (Array.isArray(arr) && arr.length > 0) return false;
    }
  }
  return extractActivityLogArrays(payload).every((a) => a.length === 0);
}

